head.script:



scwin.onpageload = function() {
	var options = $p.getOptions();
    scwin.set(options.date);
};

scwin.onbeforepageunload = function() {
    console.log($p.id + "onbeforepageunload" + "_sub2");
};

scwin.set = function(v) {
   if (!v) {
       v = "ABCDEFGHIJKLMNOPQR";
   }
   var ef = Math.ceil(v.length/3);
   var ef2 = Math.ceil(v.length * 2 / 3);
   textbox1.setValue(v.slice(0,ef));
   textbox2.setValue(v.slice(ef,ef2));
   textbox3.setValue(v.slice(ef2));
}

scwin.setInputReadOnly = function(f) {
    textbox1.setDisabled(f);
    textbox2.setDisabled(f);
    textbox3.setDisabled(f);
    var dcs = "w2textbox_disabled";
    if (f) {
        textbox1.addClass(dcs);
        textbox2.addClass(dcs);
        textbox3.addClass(dcs);
    } else {
        textbox1.removeClass(dcs);
        textbox2.removeClass(dcs);
        textbox3.removeClass(dcs);
    }
}
